#!/bin/bash\n\n# Investor Contact - Local Setup Script\n# Run this after cloning to set up development environment\n\nset -e\n\necho \"🚀 Setting up Investor Contact...\"\necho \"\"\n\n# Check Node.js\nif ! command -v node &> /dev/null; then\n    echo \"❌ Node.js not found. Please install Node.js 18+\"\n    exit 1\nfi\necho \"✅ Node.js $(node -v)\"\n\n# Check npm\nif ! command -v npm &> /dev/null; then\n    echo \"❌ npm not found\"\n    exit 1\nfi\necho \"✅ npm $(npm -v)\"\n\necho \"\"\necho \"📦 Installing dependencies...\"\nnpm install\n\necho \"\"\necho \"📝 Creating .env.local...\"\nif [ -f .env.local ]; then\n    echo \"⚠️  .env.local already exists. Skipping.\"\nelse\n    cat > .env.local << 'EOF'\nNEXT_PUBLIC_SUPABASE_URL=your-supabase-url\nNEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY=your-publishable-key\nSTRIPE_SECRET_KEY=sk_test_...\nSTRIPE_WEBHOOK_SECRET=whsec_...\nSTRIPE_FOUNDER_PRICE_ID=price_...\nSTRIPE_INVESTOR_PRICE_ID=price_...\nNEXT_PUBLIC_SITE_URL=http://localhost:3000\nEOF\n    echo \"✅ .env.local created. Update with your credentials.\"\nfi\n\necho \"\"\necho \"✅ Setup complete!\"\necho \"\"\necho \"📖 Next steps:\"\necho \"1. Update .env.local with your Supabase and Stripe credentials\"\necho \"2. Run: npm run dev\"\necho \"3. Open: http://localhost:3000\"\necho \"\"\necho \"🔗 Resources:\"\necho \"- Supabase Dashboard: https://app.supabase.com\"\necho \"- Stripe Dashboard: https://dashboard.stripe.com\"\necho \"- Deployment Guide: See DEPLOYMENT.md\"\necho \"\"\n